package main

import (
	"bufio"
	"fmt"
	"os"
)

func bad(a, b, c, l int64) int64 {
	var res int64 = 0
	for d := int64(0); d <= l; d++ {
		s := a + d - b - c
		if s < 0 {
			continue
		}
		m := l - d
		if s < m {
			m = s
		}
		res += (m + 1) * (m + 2) / 2
	}
	return res
}

func main() {
	reader := bufio.NewReader(os.Stdin)
	var a, b, c, l int64
	fmt.Fscan(reader, &a, &b, &c, &l)
	total := (l + 1) * (l + 2) * (l + 3) / 6
	total -= bad(a, b, c, l)
	total -= bad(b, a, c, l)
	total -= bad(c, a, b, l)
	fmt.Println(total)
}
